// profileCache.ts
type Entry<T> = { value: T; expires: number };

export class TtlCache<T> {
  private entries = new Map<string, Entry<T>>();
  private inFlight = new Map<string, Promise<T>>();

  constructor(private ttlMs = 60_000, private maxEntries = 10_000) {}

  async get(key: string, load: () => Promise<T>): Promise<T> {
    const hit = this.entries.get(key);
    if (hit && hit.expires > Date.now()) {
      // Re-insert to mark as most recently used.
      this.entries.delete(key);
      this.entries.set(key, hit);
      return hit.value;
    }

    // Concurrent misses share one upstream call.
    const pending = this.inFlight.get(key);
    if (pending) return pending;

    const p: Promise<T> = load()
      .then((value) => {
        // Skip the write if the key was invalidated mid-load.
        if (this.inFlight.get(key) === p) this.set(key, value);
        return value;
      })
      .finally(() => {
        if (this.inFlight.get(key) === p) this.inFlight.delete(key);
      });
    this.inFlight.set(key, p);
    return p;
  }

  set(key: string, value: T): void {
    this.entries.delete(key);
    this.entries.set(key, { value, expires: Date.now() + this.ttlMs });
    if (this.entries.size > this.maxEntries) {
      // Map iterates in insertion order, so the first key is least recently used.
      this.entries.delete(this.entries.keys().next().value!);
    }
  }

  invalidate(key: string): void {
    this.entries.delete(key);
    this.inFlight.delete(key);
  }
}
